CREATE TABLE MD_COUNTRY_GROUP (
  GROUP_ID NUMBER PRIMARY KEY, GROUP_CODE VARCHAR2(30) NOT NULL UNIQUE,
  SCOPE VARCHAR2(10) NOT NULL, SOURCE VARCHAR2(10) NOT NULL,
  NAME_TH VARCHAR2(100), NAME_EN VARCHAR2(100),
  SORT_ORDER NUMBER DEFAULT 0, IS_ACTIVE CHAR(1) DEFAULT 'Y',
  CREATED_DATE DATE DEFAULT SYSDATE
);

CREATE TABLE MD_COUNTRY_GROUP_NODE (
  NODE_ID NUMBER PRIMARY KEY, GROUP_ID NUMBER NOT NULL,
  PARENT_NODE_ID NUMBER, NODE_TYPE VARCHAR2(20) NOT NULL,
  NAME_EN VARCHAR2(200), NAME_TH VARCHAR2(200),
  COUNTRY_ID NUMBER, SORT_ORDER NUMBER DEFAULT 0,
  IS_OTHERS CHAR(1) DEFAULT 'N', IS_SUMMARY CHAR(1) DEFAULT 'N',
  CONSTRAINT FK_MCGN_GROUP FOREIGN KEY (GROUP_ID) REFERENCES MD_COUNTRY_GROUP(GROUP_ID),
  CONSTRAINT FK_MCGN_PARENT FOREIGN KEY (PARENT_NODE_ID) REFERENCES MD_COUNTRY_GROUP_NODE(NODE_ID)
);

CREATE INDEX IDX_MCGN_GROUP ON MD_COUNTRY_GROUP_NODE(GROUP_ID);
CREATE INDEX IDX_MCGN_PARENT ON MD_COUNTRY_GROUP_NODE(PARENT_NODE_ID);
CREATE INDEX IDX_MCGN_COUNTRY ON MD_COUNTRY_GROUP_NODE(COUNTRY_ID);



CREATE SEQUENCE SEQ_MD_COUNTRY_GROUP START WITH 5 INCREMENT BY 1;
